CREATE OR REPLACE FUNCTION public.save_customer_site_profile(kind text, target_id uuid, target_branch_id uuid, values_json jsonb, expected_json jsonb, change_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  previous jsonb;
  base_values jsonb;
  base_expected jsonb;
  extra_fields text[];
  field_name text;
  owner_id uuid;
  owner_allowed boolean;
begin
  if auth.uid() is null or not private.has_permission(target_branch_id, 'customers.manage') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if kind = 'customers' then
    extra_fields := array['tier_code', 'payment_terms_days', 'internal_note', 'sales_owner_employee_id', 'credit_limit_vnd'];
    if values_json ? 'tier_code' and not private.has_permission(target_branch_id, 'pricing.manage') then
      raise exception 'pricing_permission_required' using errcode = '42501';
    end if;
    if values_json ? 'credit_limit_vnd' and not private.has_permission(target_branch_id, 'finance.ar.adjust') then
      raise exception 'credit_limit_permission_required' using errcode = '42501';
    end if;
    select to_jsonb(c) into previous from public.customers c where c.id = target_id for update;
  elsif kind = 'sites' then
    extra_fields := array['latitude', 'longitude', 'sales_owner_employee_id'];
    select to_jsonb(s) into previous from public.customer_sites s where s.id = target_id for update;
    if (values_json ? 'latitude') <> (values_json ? 'longitude') then
      raise exception 'coordinate_pair_required' using errcode = '22023';
    end if;
  else
    raise exception 'unsupported_profile' using errcode = '22023';
  end if;

  if values_json ? 'sales_owner_employee_id'
    and nullif(values_json->>'sales_owner_employee_id', '') is not null
    and (previous is null or previous->>'sales_owner_employee_id' is distinct from values_json->>'sales_owner_employee_id') then
    begin
      owner_id := (values_json->>'sales_owner_employee_id')::uuid;
    exception when invalid_text_representation then
      raise exception 'invalid_sales_owner' using errcode = '22023';
    end;
    select exists(select 1 from public.employees e join public.employee_branch_access a on a.employee_id = e.id
      where e.id = owner_id and e.active and a.branch_id = target_branch_id and a.active)
      into owner_allowed;
    if not owner_allowed then raise exception 'sales_owner_outside_branch' using errcode = '42501'; end if;
  end if;

  if previous is not null then
    if expected_json is null then raise exception 'record_already_exists' using errcode = '23505'; end if;
    foreach field_name in array extra_fields loop
      if values_json ? field_name then
        if not expected_json ? field_name then raise exception 'stale_record_reload' using errcode = 'PT409'; end if;
        if field_name in ('latitude', 'longitude', 'payment_terms_days', 'credit_limit_vnd') then
          if (previous->>field_name)::numeric is distinct from (expected_json->>field_name)::numeric then
            raise exception 'stale_record_reload' using errcode = 'PT409';
          end if;
        elsif previous->>field_name is distinct from expected_json->>field_name then
          raise exception 'stale_record_reload' using errcode = 'PT409';
        end if;
      end if;
    end loop;
  elsif expected_json is not null then
    raise exception 'record_missing' using errcode = 'PT409';
  end if;

  base_values := values_json - extra_fields;
  base_expected := case when expected_json is null then null else expected_json - extra_fields end;
  begin
    perform public.save_catalog_record(kind, target_id, target_branch_id, base_values,
      base_expected, change_reason, operation_id);
  exception when sqlstate '40001' then
    raise exception 'stale_record_reload' using errcode = 'PT409';
  end;

  if kind = 'customers' then
    update public.customers c set
      tier_code = case when values_json ? 'tier_code' then nullif(values_json->>'tier_code', '') else c.tier_code end,
      payment_terms_days = case when values_json ? 'payment_terms_days' then (values_json->>'payment_terms_days')::integer else c.payment_terms_days end,
      internal_note = case when values_json ? 'internal_note' then nullif(values_json->>'internal_note', '') else c.internal_note end,
      sales_owner_employee_id = case when values_json ? 'sales_owner_employee_id' then nullif(values_json->>'sales_owner_employee_id', '')::uuid else c.sales_owner_employee_id end,
      credit_limit_vnd = case when values_json ? 'credit_limit_vnd' then nullif(values_json->>'credit_limit_vnd', '')::bigint else c.credit_limit_vnd end
    where c.id = target_id and c.branch_id = target_branch_id;
  else
    update public.customer_sites s set
      latitude = case when values_json ? 'latitude' then nullif(values_json->>'latitude', '')::numeric else s.latitude end,
      longitude = case when values_json ? 'longitude' then nullif(values_json->>'longitude', '')::numeric else s.longitude end,
      sales_owner_employee_id = case when values_json ? 'sales_owner_employee_id' then nullif(values_json->>'sales_owner_employee_id', '')::uuid else s.sales_owner_employee_id end
    where s.id = target_id;
  end if;

  if values_json ?| extra_fields then
    insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type,
      entity_id, trace_id, changed_fields, reason)
    values(auth.uid(), target_branch_id, 'profile.save',
      case when kind = 'customers' then 'customers' else 'customer_sites' end,
      target_id, operation_id,
      array(select key from jsonb_object_keys(values_json) as key where key = any(extra_fields)),
      change_reason);
  end if;
  return target_id;
end $function$
